struct string_rep { char* data; int capacity; int length; };
struct stringx { int reserved; string_rep* rep; };
struct region;
struct portal;
struct graph_node { void* edges; region* data; };
struct value_type { stringx first; graph_node second; };
struct node { int color; node* parent; node* left; node* right; value_type value; };

struct iterator {
  node* _M_node;
  iterator(node* x) : _M_node(x) {}
  void decrement() {
    if (_M_node->color == 0 && _M_node->parent->parent == _M_node)
      _M_node = _M_node->right;
    else if (_M_node->left != 0) {
      node* y = _M_node->left;
      while (y->right != 0) y = y->right;
      _M_node = y;
    } else {
      node* y = _M_node->parent;
      while (_M_node == y->left) {
        _M_node = y;
        y = y->parent;
      }
      _M_node = y;
    }
  }
};

static inline bool less_string(const stringx& a, const stringx& b) {
  int n = a.rep->length < b.rep->length ? a.rep->length : b.rep->length;
  for (int i = 0; i < n; ++i) {
    signed char ac = a.rep->data[i];
    signed char bc = b.rep->data[i];
    if (ac < bc) return true;
    if (bc < ac) return false;
  }
  return a.rep->length < b.rep->length;
}

