result insert_unique(tree* self, const value_type& __v) {
  node* __y = self->header;
  node* __x = self->header->parent;
  bool __comp = true;
  while (__x != 0) {
    __y = __x;
    __comp = less_string(__v.first, __x->value.first);
    __x = __comp ? __x->left : __x->right;
  }
  iterator __j = iterator(__y);
  if (__comp)
    if (__j._M_node == self->header->left)
      return result{insert_node(self, __x, __y, __v), true};
    else
      __j.decrement();
  if (less_string(__j._M_node->value.first, __v.first))
    return result{insert_node(self, __x, __y, __v), true};
  return result{__j, false};
}
